CREATE DATABASE IF NOT EXISTS maison_shop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE maison_shop;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,description TEXT NOT NULL,category VARCHAR(80) NOT NULL,price DECIMAL(10,2) NOT NULL,stock INT UNSIGNED NOT NULL DEFAULT 0,image VARCHAR(500),is_featured TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(category,is_active)) ENGINE=InnoDB;
CREATE TABLE orders(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,customer_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,address VARCHAR(255) NOT NULL,postal_code VARCHAR(20) NOT NULL,city VARCHAR(100) NOT NULL,subtotal DECIMAL(10,2) NOT NULL,shipping DECIMAL(10,2) NOT NULL,total DECIMAL(10,2) NOT NULL,payment_method VARCHAR(40) NOT NULL DEFAULT 'demo',status ENUM('new','processing','shipped','completed','cancelled') NOT NULL DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE order_items(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id INT UNSIGNED NOT NULL,product_id INT UNSIGNED NULL,product_name VARCHAR(180) NOT NULL,unit_price DECIMAL(10,2) NOT NULL,quantity INT UNSIGNED NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
